{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.FACT_PARETO_SLAB_PERFORMANCE_META AS WITH DATE_PARAMS_GENERATOR AS ( SELECT SEQ.MONTH_OFFSET, TO_CHAR(DATEADD(\'MONTH\', -SEQ.MONTH_OFFSET, DATE_TRUNC(\'MONTH\', CURRENT_DATE())), \'YYYY-MM\') AS REPORT_MONTH, TO_CHAR(DATEADD(\'MONTH\', -SEQ.MONTH_OFFSET, DATE_TRUNC(\'MONTH\', CURRENT_DATE())), \'Mon YYYY\') AS MONTH_LABEL, DATEADD(\'MONTH\', -SEQ.MONTH_OFFSET, DATE_TRUNC(\'MONTH\', CURRENT_DATE())) AS START_DATE, CASE WHEN SEQ.MONTH_OFFSET = 0 THEN CURRENT_DATE() ELSE LAST_DAY(DATEADD(\'MONTH\', -SEQ.MONTH_OFFSET, DATE_TRUNC(\'MONTH\', CURRENT_DATE()))) END AS END_DATE FROM (SELECT 0 AS MONTH_OFFSET UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3) SEQ ), LATEST_INV_DATES AS ( SELECT P.REPORT_MONTH, P.MONTH_LABEL, P.START_DATE, P.END_DATE, COALESCE(MAX(I.DATE), P.END_DATE) AS MAX_INV_DATE FROM DATE_PARAMS_GENERATOR P LEFT JOIN SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I ON I.DATE <= P.END_DATE GROUP BY P.REPORT_MONTH, P.MONTH_LABEL, P.START_DATE, P.END_DATE, P.MONTH_OFFSET ), SKU_META_MASTER AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, MAX( CASE WHEN CATEGORY IS NOT NULL THEN UPPER(CATEGORY) ELSE CASE WHEN LOWER(LEFT(SKU_GROUP, 5)) IN (\'4msfr\',\'4lshs\',\'4bshs\',\'4lsfs\',\'4bsfs\',\'4lswt\',\'4bswt\') THEN CASE WHEN LOWER(LEFT(SKU_GROUP, 5)) = \'4msfr\' THEN \'PERFUMES\' WHEN LOWER(LEFT(SKU_GROUP, 5)) IN (\'4lshs\',\'4bshs\',\'4lsfs\',\'4bsfs\') THEN \'SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 5)) IN (\'4lswt\',\'4bswt\') THEN \'SWEATSHIRTS\' END WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4mss\' THEN \'SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4mst\' THEN \'T-SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4msr\' THEN \'TROUSERS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4msh\' THEN \'SHORTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4mvk\' THEN \'JEANS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4mtp\' THEN \'JOGGERS AND TRACKPANTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4msn\' THEN \'SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4msd\' THEN \'JEANS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4mtr\' THEN \'CHINOS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4msw\' THEN \'SWEATERS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4shs\' THEN \'SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4sfs\' THEN \'SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4swt\' THEN \'SWEATSHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4sho\' THEN \'SHOES\' WHEN LOWER(LEFT(SKU_GROUP, 4)) = \'4tru\' THEN \'INNERWEAR\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lrn\',\'4brn\',\'4lpl\',\'4bpl\') THEN \'T-SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4ltr\',\'4btr\',\'4lch\',\'4bch\') THEN \'TROUSERS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lje\',\'4bje\') THEN \'JEANS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4ljk\',\'4bjk\') THEN \'JACKETS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lsw\',\'4bsw\') THEN \'SWEATERS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lhd\',\'4bhd\') THEN \'HOODIES\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4los\',\'4bos\') THEN \'OVERSHIRT\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lsh\',\'4bsh\') THEN \'SHORTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lbl\',\'4bbl\') THEN \'BLAZERS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lca\',\'4bca\') THEN \'CARGO PANTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4lcd\',\'4bcd\') THEN \'COORDS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4ljo\',\'4bjo\') THEN \'JOGGERS & TRACKPANTS\' WHEN LOWER(LEFT(SKU_GROUP, 4)) IN (\'4mcp\',\'4mbd\') THEN \'ACCESSORIES\' WHEN LOWER(LEFT(SKU_GROUP, 3)) IN (\'4rn\',\'4pl\') THEN \'T-SHIRTS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) IN (\'4tr\',\'4ch\') THEN \'TROUSERS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4je\' THEN \'JEANS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4jk\' THEN \'JACKETS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4sw\' THEN \'SWEATERS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4hd\' THEN \'HOODIES\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4os\' THEN \'OVERSHIRT\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4sh\' THEN \'SHORTS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4bl\' THEN \'BLAZERS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4ca\' THEN \'CARGO PANTS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4cd\' THEN \'COORDS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4jo\' THEN \'JOGGERS & TRACKPANTS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4bx\' THEN \'BOXERS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4bg\' THEN \'BAGS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4br\' THEN \'INNERWEAR\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4ac\' THEN \'ACCESSORIES\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4su\' THEN \'SUNGLASSES\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4bt\' THEN \'BELTS\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4pr\' THEN \'PERFUMES\' WHEN LOWER(LEFT(SKU_GROUP, 3)) = \'4py\' THEN \'PYJAMAS\' WHEN LOWER(LEFT(SKU_GROUP, 2)) = \'bp\' THEN \'BAGS\' WHEN LOWER(LEFT(SKU_GROUP, 2)) = \'sh\' THEN \'SHOES\' WHEN LOWER(LEFT(SKU_GROUP, 2)) = \'sn\' THEN \'SUNGLASSES\' ELSE \'UNKNOWN\' END END ) AS CATEGORY, COALESCE(MAX( CASE WHEN UPPER(STYLE) LIKE \'%LUXE%\' OR UPPER(SKU_GROUP) LIKE \'4MLX%\' OR UPPER(SKU_GROUP) LIKE \'4LRN%\' THEN \'LUXE\' WHEN UPPER(STYLE) LIKE \'%PLUS%\' OR UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' THEN \'PLUS\' ELSE \'SNITCH\' END ), \'SNITCH\') AS STYLE, COALESCE(MAX( CASE WHEN UPPER(CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN TRIM(LOWER(COLLAR_NEW)) IN (\'polo\',\'cuban\',\'baseball\',\'mandarin\',\'mock\',\'high neck\',\'zip\',\'spread\') THEN \'POLO\' ELSE \'ROUND\' END WHEN UPPER(CATEGORY) = \'SHIRTS\' THEN CASE WHEN LOWER(STYLE) LIKE \'%linen%\' OR UPPER(MATERIAL_NEW) = \'LINEN\' THEN \'LINEN\' WHEN UPPER(MATERIAL_NEW) = \'COTTON\' THEN \'COTTON\' ELSE \'POLYESTER\' END WHEN UPPER(CATEGORY) IN (\'TROUSERS\', \'CHINOS\') THEN CASE WHEN UPPER(FIT) IN (\'SLIM FIT\') THEN \'SLIM FIT\' ELSE \'STRAIGHT FIT\' END WHEN UPPER(CATEGORY) = \'JEANS\' THEN CASE WHEN UPPER(FIT) = \'SLIM FIT\' THEN \'SLIM FIT\' WHEN UPPER(FIT) = \'SKINNY FIT\' THEN \'SKINNY FIT\' ELSE \'STRAIGHT FIT\' END END ), \'NA\') AS META1, COALESCE(MAX( CASE WHEN UPPER(CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN UPPER(TRIM(STYLE)) LIKE \'%TECHNICAL%\' THEN \'TECHNICAL\' WHEN UPPER(TRIM(DESIGNS)) = \'SOLID\' THEN \'CORE\' ELSE \'FASHION\' END WHEN UPPER(CATEGORY) = \'SHIRTS\' THEN CASE WHEN UPPER(TRIM(DESIGNS)) = \'SOLID\' THEN \'SOLID\' WHEN UPPER(TRIM(DESIGNS)) = \'STRIPES\' THEN \'STRIPES\' ELSE \'PRINTED\' END END ), \'NA\') AS META2, COALESCE(MAX( CASE WHEN UPPER(CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN UPPER(TRIM(FIT)) IN (\'OVERSIZED\',\'BOX FIT\',\'RELAXED FIT\') THEN \'OVERSIZED FIT\' WHEN UPPER(TRIM(FIT)) = \'SLIM FIT\' THEN \'SLIM FIT\' ELSE \'REGULAR FIT\' END END ), \'NA\') AS META3 FROM SNITCH_DB.MAPLEMONK.METAFIELDS_DATA GROUP BY REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') ), SKU_CATALOG_PRICES AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, AVG(CAST(PRICE AS NUMBER(10,2))) AS CATALOG_MRP FROM SNITCH_DB.MAPLEMONK.AVAILABILITY_MASTER_V2 WHERE PRICE IS NOT NULL AND PRICE > 0 GROUP BY REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') ), SKU_SALES_PRICES AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, AVG(CAST(COALESCE(SELLING_PRICE, MRP) AS NUMBER(10,2))) AS HISTORICAL_PRICE FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE COALESCE(SELLING_PRICE, MRP) > 0 GROUP BY REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') ), SKU_MASTER_PRICES AS ( SELECT COALESCE(C.CLEAN_SKU_GROUP, S.CLEAN_SKU_GROUP) AS CLEAN_SKU_GROUP, COALESCE(C.CATALOG_MRP, S.HISTORICAL_PRICE) AS SKU_PRICE FROM SKU_CATALOG_PRICES C FULL OUTER JOIN SKU_SALES_PRICES S ON C.CLEAN_SKU_GROUP = S.CLEAN_SKU_GROUP ), META_AVG_PRICES AS ( SELECT M.CATEGORY, M.STYLE, M.META1, M.META2, M.META3, AVG(P.SKU_PRICE) AS META_DEFAULT_PRICE FROM SKU_META_MASTER M INNER JOIN SKU_MASTER_PRICES P ON M.CLEAN_SKU_GROUP = P.CLEAN_SKU_GROUP GROUP BY M.CATEGORY, M.STYLE, M.META1, M.META2, M.META3 ), CATEGORY_AVG_PRICES AS ( SELECT M.CATEGORY, AVG(P.SKU_PRICE) AS CAT_DEFAULT_PRICE FROM SKU_META_MASTER M INNER JOIN SKU_MASTER_PRICES P ON M.CLEAN_SKU_GROUP = P.CLEAN_SKU_GROUP GROUP BY M.CATEGORY ), INV_SLABS AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, I.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', I.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'UNMAPPED_CLUSTER\') AS CLUSTER_NAME, META.CATEGORY, META.STYLE, META.META1, META.META2, META.META3, R.PRICE_SLAB_CODE, R.PRICE_RANGE_LABEL, (COALESCE(I.INVENTORY, 0) + COALESCE(I.JIT_QTY, 0)) AS INV_UNITS_CLOSING FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I INNER JOIN LATEST_INV_DATES L ON I.DATE = L.MAX_INV_DATE LEFT JOIN SKU_META_MASTER META ON REGEXP_REPLACE(UPPER(TRIM(I.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = META.CLEAN_SKU_GROUP LEFT JOIN SKU_MASTER_PRICES P ON REGEXP_REPLACE(UPPER(TRIM(I.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = P.CLEAN_SKU_GROUP LEFT JOIN META_AVG_PRICES MA ON EQUAL_NULL(META.CATEGORY, MA.CATEGORY) AND EQUAL_NULL(META.STYLE, MA.STYLE) AND EQUAL_NULL(META.META1, MA.META1) AND EQUAL_NULL(META.META2, MA.META2) AND EQUAL_NULL(META.META3, MA.META3) LEFT JOIN CATEGORY_AVG_PRICES CA ON EQUAL_NULL(META.CATEGORY, CA.CATEGORY) INNER JOIN SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS_META R ON EQUAL_NULL(META.CATEGORY, R.CATEGORY) AND EQUAL_NULL(META.STYLE, R.STYLE) AND EQUAL_NULL(META.META1, R.META1) AND EQUAL_NULL(META.META2, R.META2) AND EQUAL_NULL(META.META3, R.META3) AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) >= R.SLAB_MIN_PRICE AND COALESCE(P.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) <= R.SLAB_MAX_PRICE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(I.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE CAST(I.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') ), OPENING_INV_SLABS AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, I.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', I.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'UNMAPPED_CLUSTER\') AS CLUSTER_NAME, META.CATEGORY, META.STYLE, META.META1, META.META2, META.META3, R.PRICE_SLAB_CODE, R.PRICE_RANGE_LABEL, (COALESCE(I.INVENTORY, 0) + COALESCE(I.JIT_QTY, 0)) AS INV_UNITS_OPENING FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I INNER JOIN LATEST_INV_DATES L ON I.DATE = L.START_DATE LEFT JOIN SKU_META_MASTER META ON REGEXP_REPLACE(UPPER(TRIM(I.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = META.CLEAN_SKU_GROUP LEFT JOIN SKU_MASTER_PRICES PC ON REGEXP_REPLACE(UPPER(TRIM(I.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = PC.CLEAN_SKU_GROUP LEFT JOIN META_AVG_PRICES MA ON EQUAL_NULL(META.CATEGORY, MA.CATEGORY) AND EQUAL_NULL(META.STYLE, MA.STYLE) AND EQUAL_NULL(META.META1, MA.META1) AND EQUAL_NULL(META.META2, MA.META2) AND EQUAL_NULL(META.META3, MA.META3) LEFT JOIN CATEGORY_AVG_PRICES CA ON EQUAL_NULL(META.CATEGORY, CA.CATEGORY) INNER JOIN SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS_META R ON EQUAL_NULL(META.CATEGORY, R.CATEGORY) AND EQUAL_NULL(META.STYLE, R.STYLE) AND EQUAL_NULL(META.META1, R.META1) AND EQUAL_NULL(META.META2, R.META2) AND EQUAL_NULL(META.META3, R.META3) AND COALESCE(PC.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) >= R.SLAB_MIN_PRICE AND COALESCE(PC.SKU_PRICE, MA.META_DEFAULT_PRICE, CA.CAT_DEFAULT_PRICE, 1200) <= R.SLAB_MAX_PRICE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(I.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE CAST(I.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') ), SALES_SLABS AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, S.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', S.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'UNMAPPED_CLUSTER\') AS CLUSTER_NAME, META.CATEGORY, META.STYLE, META.META1, META.META2, META.META3, S.SHIPPING_QUANTITY AS QUANTITY, (S.SHIPPING_QUANTITY * S.SELLING_PRICE) AS REVENUE, R.PRICE_SLAB_CODE, R.PRICE_RANGE_LABEL FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE S INNER JOIN LATEST_INV_DATES L ON S.ORDER_DATE >= L.START_DATE AND S.ORDER_DATE <= L.END_DATE LEFT JOIN SKU_META_MASTER META ON REGEXP_REPLACE(UPPER(TRIM(S.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = META.CLEAN_SKU_GROUP INNER JOIN SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS_META R ON EQUAL_NULL(META.CATEGORY, R.CATEGORY) AND EQUAL_NULL(META.STYLE, R.STYLE) AND EQUAL_NULL(META.META1, R.META1) AND EQUAL_NULL(META.META2, R.META2) AND EQUAL_NULL(META.META3, R.META3) AND COALESCE(S.SELLING_PRICE, S.MRP) >= R.SLAB_MIN_PRICE AND COALESCE(S.SELLING_PRICE, S.MRP) <= R.SLAB_MAX_PRICE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(S.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE LOWER(S.ORDER_STATUS) LIKE \'%process%\' AND S.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') AND CAST(S.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') ), COMBINED_METRICS AS ( SELECT REPORT_MONTH, MONTH_LABEL, BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, 0 AS INV_UNITS_CLOSING, 0 AS INV_UNITS_OPENING, QUANTITY AS SALES_QTY, REVENUE FROM SALES_SLABS UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, INV_UNITS_CLOSING, 0 AS INV_UNITS_OPENING, 0 AS SALES_QTY, 0 AS REVENUE FROM INV_SLABS UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, 0 AS INV_UNITS_CLOSING, INV_UNITS_OPENING, 0 AS SALES_QTY, 0 AS REVENUE FROM OPENING_INV_SLABS ), UNIFIED_AGGREGATE AS ( SELECT REPORT_MONTH, MONTH_LABEL, \'1. Company Wide\' AS HIERARCHY_LEVEL, \'ALL STORES\' AS LOCATION_ID, \'National (All Stores)\' AS LOCATION_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(INV_UNITS_CLOSING) AS STORE_INV_UNITS_CLOSING, SUM(INV_UNITS_OPENING) AS STORE_INV_UNITS_OPENING, SUM(SALES_QTY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM COMBINED_METRICS GROUP BY REPORT_MONTH, MONTH_LABEL, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, \'2. Cluster Wise\' AS HIERARCHY_LEVEL, CLUSTER_NAME AS LOCATION_ID, CONCAT(CLUSTER_NAME, \' Cluster\') AS LOCATION_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(INV_UNITS_CLOSING) AS STORE_INV_UNITS_CLOSING, SUM(INV_UNITS_OPENING) AS STORE_INV_UNITS_OPENING, SUM(SALES_QTY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM COMBINED_METRICS GROUP BY REPORT_MONTH, MONTH_LABEL, CLUSTER_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, \'3. Store Wise\' AS HIERARCHY_LEVEL, CAST(BRANCH_CODE AS VARCHAR) AS LOCATION_ID, STORE_NAME AS LOCATION_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(INV_UNITS_CLOSING) AS STORE_INV_UNITS_CLOSING, SUM(INV_UNITS_OPENING) AS STORE_INV_UNITS_OPENING, SUM(SALES_QTY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM COMBINED_METRICS GROUP BY REPORT_MONTH, MONTH_LABEL, BRANCH_CODE, STORE_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL ), PARETO_CALC AS ( SELECT REPORT_MONTH, MONTH_LABEL, HIERARCHY_LEVEL, LOCATION_ID, LOCATION_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, STORE_INV_UNITS_CLOSING, STORE_INV_UNITS_OPENING, ROUND(100.0 * STORE_INV_UNITS_CLOSING / NULLIF(SUM(STORE_INV_UNITS_CLOSING) OVER (PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY, STYLE, META1, META2, META3), 0), 2) AS INV_SHARE_PCT, SALES_UNITS, SALES_REVENUE, ROUND(100.0 * SALES_UNITS / NULLIF(SUM(SALES_UNITS) OVER (PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY, STYLE, META1, META2, META3), 0), 2) AS SALES_SHARE_PCT, SUM(SALES_UNITS) OVER ( PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY, STYLE, META1, META2, META3 ORDER BY SALES_UNITS DESC, PRICE_SLAB_CODE ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) / NULLIF(SUM(SALES_UNITS) OVER (PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY, STYLE, META1, META2, META3), 0) AS CUMULATIVE_SHARE, ROUND(SALES_UNITS / NULLIF(SALES_UNITS + STORE_INV_UNITS_CLOSING, 0), 4) AS STR1, ROUND(SALES_UNITS / NULLIF((STORE_INV_UNITS_OPENING + STORE_INV_UNITS_CLOSING) / 2.0, 0), 4) AS STR2, ROUND(SALES_UNITS / NULLIF(STORE_INV_UNITS_OPENING, 0), 4) AS STR3 FROM UNIFIED_AGGREGATE ), STR3_PARETO_CALC AS ( SELECT *, SUM(COALESCE(STR3, 0)) OVER ( PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY, STYLE, META1, META2, META3 ORDER BY COALESCE(STR3, 0) DESC, PRICE_SLAB_CODE ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) / NULLIF(SUM(COALESCE(STR3, 0)) OVER (PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY, STYLE, META1, META2, META3), 0) AS CUMULATIVE_STR3_SHARE FROM PARETO_CALC ) SELECT REPORT_MONTH, MONTH_LABEL, HIERARCHY_LEVEL, LOCATION_ID, LOCATION_NAME, CATEGORY, STYLE, META1, META2, META3, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, STORE_INV_UNITS_CLOSING, INV_SHARE_PCT, SALES_UNITS, SALES_REVENUE, SALES_SHARE_PCT, ROUND(CUMULATIVE_SHARE * 100, 2) AS CUMULATIVE_SALES_SHARE_PCT, CASE WHEN CUMULATIVE_SHARE <= 0.50 THEN \'A\' WHEN CUMULATIVE_SHARE <= 0.80 THEN \'B\' WHEN CUMULATIVE_SHARE <= 0.95 THEN \'C\' ELSE \'D\' END AS PARETO_ABCD_RANK, STORE_INV_UNITS_OPENING, STR1, STR2, STR3, ROUND(CUMULATIVE_STR3_SHARE * 100, 2) AS CUMULATIVE_STR3_SHARE_PCT, CASE WHEN CUMULATIVE_STR3_SHARE <= 0.50 THEN \'A\' WHEN CUMULATIVE_STR3_SHARE <= 0.80 THEN \'B\' WHEN CUMULATIVE_STR3_SHARE <= 0.95 THEN \'C\' ELSE \'D\' END AS STR3_PARETO_ABCD_RANK, CURRENT_TIMESTAMP() AS UPDATED_AT FROM STR3_PARETO_CALC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
